import java.util.*;

class Solution {
  public int[] threeEqualParts(int[] arr) {
    int ones = 0;
    for (int x : arr) ones += x;
    if (ones == 0) return new int[] {0, arr.length - 1};
    if (ones % 3 != 0) return new int[] {-1, -1};
    int k = ones / 3, first = -1, second = -1, third = -1, seen = 0;
    for (int i = 0; i < arr.length; i++)
      if (arr[i] == 1) {
        seen++;
        if (seen == 1) first = i;
        if (seen == k + 1) second = i;
        if (seen == 2 * k + 1) third = i;
      }
    int len = arr.length - third;
    if (first + len > second || second + len > third) return new int[] {-1, -1};
    for (int i = 0; i < len; i++)
      if (arr[first + i] != arr[second + i] || arr[first + i] != arr[third + i])
        return new int[] {-1, -1};
    return new int[] {first + len - 1, second + len};
  }
}
